// Sprint 3: product rules and navigable, entirely simulated scenarios.
// No real location, media, payments or transport API is collected here.
const demo = { date: '13/09/2026', day: '2026-09-13', week: '7 a 13 de setembro', month: 'Setembro de 2026', impact: 68, rewardBudget: 36 };
const labels = {validated:'Validada', inconclusive:'Inconclusiva', rejected:'Não validada', cancelled:'Cancelada'};
const row = (title, text, glyph='shield') => `<div class="info-row">${icon(glyph)}<div><strong>${title}</strong><span>${text}</span></div></div>`;
const button = (label, action, style='secondary-button', attrs='') => `<button type="button" class="${style}" data-action="${action}" ${attrs}>${label}</button>`;
const field = (label,id,options) => `<label class="move-field">${label}<select id="${id}">${options.map(([value,text])=>`<option value="${value}">${text}</option>`).join('')}</select></label>`;
const selectedResult = () => state.journeys.find(j=>j.id===state.selectedJourney) || state.journeys.at(-1);
function weekOf(day){const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
const demoEnd = () => demo.day+'T12:00:00-03:00';
const endDay = timestamp => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(timestamp));
const competitive = (cycle='week',day=demo.day) => state.journeys.filter(j=>j.rankingEligible&&(cycle==='month'?j.day.slice(0,7)===day.slice(0,7):j.week===weekOf(day))).reduce((sum,j)=>sum+j.impact,0);
const weeklyAwards = () => state.journeys.filter(j=>j.recognition&&j.week===weekOf(demo.day));
function recognitionCard(j){const a=j.recognition;return `<article class="recognition-card"><span class="member-photo member-carlos" role="img" aria-label="Carlos Eduardo"></span><div><small>CONQUISTA SEMANAL · ${a.ordinal}/2</small><h3>${a.ordinal===1?'Primeiro passo':'Ritmo da semana'}</h3><p>Carlos Eduardo · ${a.position}º na amostra da Liga</p><p>${a.points} Pontos de Impacto · posição no desbloqueio</p>${button('Abrir cartão','recognition-share','text-link',`data-id="${j.id}"`)}</div></article>`}
function screen(title,body,footer='') { return innerScreen(title,`<section class="page move-page">${body}</section>`,footer?`<footer class="sticky-action">${footer}</footer>`:''); }
function renderMoveHome(){
 const valid=state.journeys.filter(j=>j.status==='validated'&&j.week===weekOf(demo.day));
 const avoided=valid.reduce((sum,j)=>sum+j.avoided,0);
 const cta=state.currentJourney?(state.currentJourney.ended?'Concluir validação':'Continuar rota'):'Iniciar rota';
 return screen('Mobilidade',`<div class="mobility-hub">
 <header class="mobility-hero"><span class="mobility-eyebrow">SOULMOVE · MISSÕES SOULUP</span><h1>Seu caminho conta.</h1><p>Esta semana · ${demo.week}</p>
 <div class="mobility-totals"><div><strong>${valid.length}</strong><span>rotas validadas</span></div><div><strong>${avoided.toLocaleString('pt-BR',{maximumFractionDigits:2})} kg</strong><span>CO₂ evitado estimado</span></div></div><small>Rotas e CO₂ registrados nesta sessão demonstrativa.</small>
 <div class="weekly-recognition"><strong>Reconhecimentos da semana · ${weeklyAwards().length}/2</strong><span>${weeklyAwards().length===2?'Os dois selos foram liberados. Continue somando impacto.':'Cada uma das duas primeiras rotas livres validadas libera um selo e um cartão.'}</span></div>
 ${button(cta,'free-journey','mobility-start')}<span class="mobility-mode">${icon('route',16)} Ônibus urbano</span></header>
 ${weeklyAwards().length?`<section class="mobility-achievements" aria-label="Suas conquistas"><h2>Suas conquistas</h2>${weeklyAwards().map(recognitionCard).join('')}</section>`:''}
 <div class="mobility-section-heading"><h2>Liga semanal</h2>${button('Ver classificação','week','text-link')}</div>
 ${renderLeagueStandings(false,340+competitive(),true)}
 <div class="mobility-section-heading"><h2>Campanhas</h2>${button('Ver missões','missions','text-link')}</div><p class="mobility-caption">Metas patrocinadas que geram Pontos Soul para sua carteira.</p>
 <article class="move-campaign"><img src="./assets/soulmove-campaign.webp" alt="Passageira em ônibus na campanha VIVA"><div><small>VIVA · 10–25 SET · DEMONSTRAÇÃO</small><h2>${campaign.title}</h2><p>3 jornadas elegíveis</p><progress max="3" value="${state.campaignProgress}" aria-label="Progresso da campanha"></progress><div class="campaign-progress-label"><span>${state.campaignProgress}/3 jornadas</span><strong>+12 Pontos Soul</strong></div>${button('Ver campanha','open-campaign')}</div></article>
 <section class="mobility-season"><span class="mobility-eyebrow">TEMPORADA MENSAL</span><h2>${demo.month}</h2><p>Até 30 de setembro</p><strong>${(1240+competitive('month')).toLocaleString('pt-BR')} <small>Pontos de Impacto</small></strong>${button('Acompanhar temporada','month','text-link')}</section>
 <nav class="mobility-tools" aria-label="Acessos da mobilidade">${button('Histórico','history','text-link')}${button('Autorizações','permissions','text-link')}</nav>
 <p class="move-demo">Dados simulados. Pontos de Impacto são classificação; Pontos Soul são recompensas de campanhas.</p></div>`);
}

function renderMissions(){
 const filter=state.missionsFilter;
 const moving=state.currentJourney||state.journeys.some(j=>j.status==='validated');
 const items=[
  {id:'mobility',status:moving?'progress':'available',title:'Mobilidade',reward:icon('route',22),description:'Pontos de Impacto para a liga',progress:`${state.journeys.filter(j=>j.status==='validated').length} rotas validadas nesta sessão`,action:'move-home',label:'Começar'},
  {id:'campaign',status:state.rewardIssued?'completed':state.joined?'progress':state.campaignStatus==='active'?'available':'closed',title:campaign.title,reward:'+12',description:'Pontos Soul · Campanha VIVA',progress:`Progresso ${state.campaignProgress}/3`,action:'open-campaign',label:state.rewardIssued?'Ver conquista':state.joined?'Continuar':'Começar'},
  {id:'posts',status:'progress',title:'Faça 30 posts no mês',reward:'+30',description:'',progress:'Progresso 12/30',action:'prototype-notice',label:'Começar'},
  {id:'communities',status:'progress',title:'Entre em 20 comunidades',reward:'+20',description:'',progress:'Progresso 1/20',action:'prototype-notice',label:'Começar'},
  {id:'follow',status:'available',title:'Siga 100 usuários',reward:'+20',description:'',progress:'',action:'prototype-notice',label:'Começar'}
 ];
 const visible=items.filter(i=>filter==='all'?i.status!=='completed'&&i.status!=='closed':i.status===filter);
 return screen('Missões',`<div class="missions-native"><header class="missions-banner"><div><h1>Complete missões e descubra <span>novas conquistas</span></h1>${button('Missões concluídas','completed-missions','missions-completed')}</div><span class="missions-banner-icon" aria-hidden="true">${icon('target',64)}</span></header>
 <h2>${filter==='completed'?'Missões concluídas':'Missões'}</h2><p class="mobility-caption">Mobilidade e campanhas dentro da SoulUP.</p>
 <nav class="missions-filters" aria-label="Filtrar missões">${[['all','Todos'],['available','Disponíveis'],['progress','Em Progresso']].map(([id,label])=>button(label,'filter-missions',`mission-chip ${filter===id?'selected':''}`,`data-filter="${id}" aria-pressed="${filter===id}"`)).join('')}</nav>
 <div class="missions-list">${visible.map(i=>`<article class="native-mission"><span class="mission-reward ${i.id==='mobility'?'impact':''}">${i.reward}</span><div class="native-mission-copy"><h3>${i.title}</h3><p>${i.description}</p><small>${i.progress}</small></div>${button(i.label,i.action,'mission-begin')}</article>`).join('')||'<p class="mission-empty">'+(filter==='completed'?'Nenhuma missão concluída nesta sessão. As campanhas concluídas aparecerão aqui.':'Nenhuma missão neste filtro. Consulte Todos para explorar as opções.')+'</p>'}</div></div>`);
}

function renderPublicAchievement(){
 return screen('Conquista compartilhada',`<h1>Mais uma jornada concluída!</h1><p>Rafael Martins · publicação demonstrativa</p><article class="achievement-post"><span class="achievement-label">JORNADA VALIDADA</span><h2>${campaign.title}</h2><div class="achievement-stats"><div><strong>7,1 km</strong><span>transporte público</span></div><div><strong>+12</strong><span>Pontos Soul</span></div><div><strong>#12</strong><span>posição compartilhada</span></div></div><p>3 de 3 jornadas · meta da campanha concluída</p></article><p>Registro público da conquista. A posição corresponde ao momento da publicação.</p>${button('Conhecer a campanha','open-campaign')}${button('Explorar mobilidade','move-home','primary-button')}`);
}
renderCampaignDetail = function(){
 return screen('Campanha patrocinada',`<div class="campaign-visual"><small>VIVA · CAMPANHA DEMONSTRATIVA</small><h1>${campaign.title}</h1><p>Reconheça os deslocamentos da sua rotina.</p></div>
 ${row('10 a 25 de setembro de 2026','Período próprio, independente da Liga e da Temporada.','clock')}
 ${row('Quem participa','Usuários SoulUP participantes da demonstração, em São Paulo.','users')}
 ${row('Meta: 3 jornadas elegíveis',`Progresso demonstrativo inicial: 2/3. Seu progresso atual: ${state.campaignProgress}/3. Até duas jornadas de campanha por dia.`, 'target')}
 ${row('Linhas elegíveis','Linhas fictícias D01 e D02, em ambos os sentidos. Neste exemplo, todos os trechos de ônibus precisam ser elegíveis. Integração não multiplica recompensa.','route')}
 ${row('12 Pontos Soul + 15% de desconto','Uma recompensa por participante ao completar a meta. Oferta válida até 30/09/2026; sem compra obrigatória.','gift')}
 ${row('Cobertura da recompensa','A adesão reserva a cobertura do limite de uma recompensa por participante. O início da jornada não faz outra reserva.','wallet')}
 ${row('Pontos de Impacto','A jornada pode contar nos rankings conforme suas regras. Pontos Soul e compras não aumentam essa pontuação.','trophy')}
 <label class="consent-option"><input type="checkbox" id="campaign-accept" ${state.campaignAccepted?'checked':''}><span><strong>Li e aceito as regras desta campanha</strong><span>Versão demonstrativa 1 · benefício e período próprios.</span></span></label>
 <p class="move-demo">Patrocínio, linhas, orçamento e condições comerciais são exemplos do protótipo.</p>`,button(state.joined?'Registrar jornada nesta campanha':'Participar da campanha','join','primary-button',state.campaignAccepted && state.campaignStatus==='active'?'':'disabled'));
};
renderConsent = function(){return screen('Autorizações',`<h1>Você controla a coleta</h1><p>Localização, tempo e checkpoints são necessários para registrar e validar uma jornada.</p>
 <label class="consent-option"><input type="checkbox" data-consent="location" ${state.consentLocation?'checked':''}><span><strong>Autorizar dados durante a jornada</strong><span>A coleta começa ao iniciar e termina ao encerrar ou cancelar. Ativar esta autorização não inicia a coleta.</span></span></label>
 <label class="consent-option"><input type="checkbox" data-consent="rules" ${state.consentRules?'checked':''}><span><strong>Li as regras do registro</strong><span>Ônibus urbano, validação por telemetria e checkpoints e impacto estimado. Foto ou vídeo são opcionais.</span></span></label>
 ${row('Sem autorização','Você pode consultar campanhas, rankings e histórico; o registro de uma jornada permanece indisponível.')}
 ${row('Foto ou vídeo','Escolha ao finalizar. Nesta demonstração, nenhum arquivo real é capturado ou enviado.','camera')}
 ${button('Revogar autorização','revoke')}`,button('Continuar','consent-continue','primary-button',state.consentLocation&&state.consentRules?'':'disabled'))};
function lineFields(){return field('Linha de ônibus','bus-line',[['D01','D01 · Centro — Terminal Norte'],['D02','D02 · Terminal Norte — Campus'],['D03','D03 · Centro — Bairro Sul (fora da campanha)']])+field('Sentido','bus-direction',[['ida','Ida'],['volta','Volta']]);}
renderReady = function(){return screen('Preparar jornada',`<h1>${state.mode==='campaign'?'Jornada com campanha':'Jornada livre'}</h1><p>Informe a linha e o sentido do primeiro ônibus.</p>${lineFields()}
 ${row('Uma jornada, vários trechos','Ao trocar de ônibus, adicione uma integração. A espera e a caminhada entre ônibus ficam fora da distância pontuada.','route')}
 ${row('Reconhecimento',state.mode==='campaign'?'Pontos de Impacto quando elegível; progresso apenas na campanha VIVA selecionada.':'Pontos de Impacto quando elegível; nenhum crédito automático de Pontos Soul.','trophy')}
 <details class="move-details"><summary>Cenário de validação da demonstração</summary>${field('Resultado simulado','demo-outcome',[['validated','Evidências coerentes'],['inconclusive','Evidências insuficientes'],['rejected','Deslocamento incompatível']])}<p>Não representa um motor antifraude implementado.</p></details>
 <p class="move-demo">Linhas fictícias e percurso simulado. Seleção automática de linha é uma evolução futura.</p>`,button('Iniciar jornada demonstrativa','start-journey','primary-button'))};
renderJourney = function(){const j=state.currentJourney;return screen('Jornada em andamento',`<span class="move-pill">Registro ativo · simulação</span><h1>Continue seu deslocamento</h1><p>Não é necessário acompanhar o celular durante o percurso.</p><div class="move-stats"><div><strong>${(j.segments.length*4.2).toFixed(1).replace('.',',')} km</strong><span>distância simulada de ônibus</span></div><div><strong>${j.segments.length*2}</strong><span>checkpoints simulados</span></div></div>
 ${j.segments.map((s,i)=>row(`Trecho ${i+1} · ${s.line}`,`${s.direction==='ida'?'Ida':'Volta'} · seleção manual · 4,2 km simulados`,'route')).join('')}
 ${row('Vínculo',j.mode==='campaign'?'Campanha VIVA selecionada no início.':'Jornada livre, sem campanha.')}
 <div class="action-stack">${button('Adicionar integração','integration')}${button('Encerrar jornada','finish-journey','primary-button')}${button('Cancelar jornada','cancel-request')}</div>`)};
function renderIntegration(){return screen('Adicionar integração',`<h1>Vai pegar outro ônibus?</h1><p>O novo trecho permanece na mesma jornada. Espera e caminhada não geram pontuação.</p>${lineFields()}${row('Sem recompensa duplicada','A integração não cria uma jornada adicional nem uma segunda recompensa.')}`,button('Adicionar trecho e continuar','add-segment','primary-button'))}
renderProof = function(){return screen('Evidências da jornada',`<h1>Registro encerrado</h1><p>A coleta foi interrompida. As evidências serão analisadas antes de definir o resultado.</p>${row('Prova principal','Telemetria e checkpoints dos trechos de ônibus registrados.','route')}<h2>Prova complementar opcional</h2><p>Você pode continuar sem foto ou vídeo.</p><div class="move-links">${button('Adicionar foto simulada','select-proof','secondary-button','data-proof="Foto"')}${button('Adicionar vídeo simulado','select-proof','secondary-button','data-proof="Vídeo"')}</div>${state.proofType?row(state.proofType+' adicionada','Anexo demonstrativo, sem envio de arquivo.','camera')+button('Remover anexo','remove-proof'):''}`,button('Enviar para validação','submit-proof','primary-button'))};
function finalizeJourney(status){
 const j=state.currentJourney;if(!j || state.journeys.some(item=>item.id===j.id)) return;
 j.endedAt ||= demoEnd();j.status=status;j.day=endDay(j.endedAt);j.week=weekOf(j.day);j.distance=j.segments.length*4.2;j.avoided=status==='validated'?Number((j.distance*1.1/8.4).toFixed(2)):0;
 j.impact=status==='validated'?demo.impact:0;j.rankingEligible=status==='validated';j.reward=0;
 j.campaignEligible=status==='validated'&&j.mode==='campaign'&&j.segments.every(s=>['D01','D02'].includes(s.line))&&state.journeys.filter(x=>x.day===j.day&&x.campaignEligible).length<2;
 if(j.campaignEligible){state.campaignProgress=Math.min(3,state.campaignProgress+1);if(state.campaignProgress===3&&!state.rewardIssued){state.rewardIssued=true;state.benefitUnlocked=true;state.points+=12;state.reservation=0;j.reward=12;}}
 if(status==='validated'&&j.mode==='free'){
  const count=state.journeys.filter(x=>x.status==='validated'&&x.mode==='free'&&x.week===j.week).length;
  if(count<2){const points=(j.week===weekOf(demo.day)?340:0)+competitive('week',j.day)+j.impact;j.recognition={ordinal:count+1,points,position:1+[680,640,602].filter(p=>p>points).length};}
 }
 state.journeys.push(j);state.selectedJourney=j.id;state.validated=state.journeys.some(x=>x.status==='validated');state.currentJourney=null;state.proofType='';
}
beginValidation = function(){if(!state.currentJourney||!state.currentJourney.ended||state.currentJourney.processing)return; state.currentJourney.processing=true; const processingId=state.currentJourney.id; state.screen='validation';render();clearJourneyTimers();setTimeout(()=>{if(!state.currentJourney?.processing||state.currentJourney.id!==processingId)return;finalizeJourney(state.outcome);state.screen='result';render()},1100);};
renderResult = function(){const j=selectedResult();if(!j)return renderHistory();const good=j.status==='validated';return screen('Resultado da jornada',`<span class="move-pill ${good?'':'move-warning'}">${labels[j.status]}</span><h1>${good?'Sua jornada foi validada':j.status==='inconclusive'?'Precisamos de mais evidências':j.status==='cancelled'?'Jornada cancelada':'Jornada não validada'}</h1>
 <p>${good?'Evidências coerentes no cenário demonstrativo.':j.status==='inconclusive'?'Os dados disponíveis não permitem confirmar o deslocamento. Isso não significa fraude.':j.status==='cancelled'?'Registro encerrado antes da validação.':'O deslocamento do cenário é incompatível com os critérios de validação. Você pode solicitar revisão.'}</p>
 <div class="move-stats"><div><strong>${j.distance.toFixed(1).replace('.',',')} km</strong><span>${j.segments.length} trecho(s) de ônibus</span></div><div><strong>${good?j.avoided.toFixed(2).replace('.',','):'—'} kg</strong><span>emissões evitadas estimadas*</span></div></div>
 ${row('Pontos de Impacto',good?`${j.impact} pontos ilustrativos. Jornada incluída na Liga e na Temporada do período de término, sem limite diário de rotas.`:'Sem pontuação para este resultado.','trophy')}
 ${j.recognition?row(`${j.recognition.ordinal}ª rota livre da semana · selo desbloqueado`,'Seu cartão personalizado de ranking também está disponível no painel Mobilidade.','badge')+recognitionCard(j):''}
 ${row('Campanha e Pontos Soul',j.reward?'+12 Pontos Soul pela meta concluída; crédito demonstrativo único.':j.mode==='free'?'Jornada livre: sem campanha e sem crédito de Pontos Soul.':j.campaignEligible?'Progresso registrado uma única vez na campanha.':good?'Jornada fora dos critérios da campanha: sem progresso ou recompensa.':'Sem progresso ou recompensa enquanto não validada.','gift')}
 ${j.appeal?row('Contestação em análise',`Protocolo ${j.appeal}. O resultado original permanece visível até a decisão.`):''}
 <div class="action-stack">${good?button('Ver Liga e Temporada','ranking')+button('Criar cartão compartilhável','share'):j.status!=='cancelled'&&!j.appeal?button('Contestar resultado','appeal'):''}${j.reward?button('Acessar benefício','benefit','primary-button'):''}${button('Ver histórico','history')}${button('Voltar ao SoulMove','move-home')}</div>
 <p class="move-demo">*Valores ilustrativos, sem cálculo ambiental auditado. Não representam créditos de carbono. Fórmula final de pontuação e metodologia em validação.</p>`)};
function renderHistory(){return screen('Histórico',`<h1>Suas jornadas</h1><p>Resultados, trechos e solicitações de revisão.</p>${state.journeys.length?state.journeys.slice().reverse().map((j,i)=>`<button type="button" class="move-history" data-action="history-result" data-id="${j.id}"><span><strong>${labels[j.status]}${j.appeal?' · contestação em análise':''}</strong><small>${j.day.split('-').reverse().join('/')} · ${j.mode==='free'?'Livre':'VIVA'} · ${j.segments.length} trecho(s)</small></span>${icon('chevron')}</button>`).join(''):row('Nenhuma jornada nesta sessão','Comece uma jornada livre ou escolha uma campanha.','route')}${button('Iniciar jornada livre','free-journey','primary-button')}`)}
function renderAppeal(){return screen('Contestar resultado',`<h1>Solicitar revisão</h1><p>Explique o que aconteceu no deslocamento. Nenhum ponto ou benefício é concedido apenas por abrir uma contestação.</p><label class="move-field">Justificativa<textarea id="appeal-reason" maxlength="600" rows="5" placeholder="Conte o que precisa ser revisto"></textarea></label>${row('Evidência complementar opcional','Nesta demonstração, a análise utiliza a justificativa e os registros simulados. Não envie documentos pessoais.')}<p class="move-demo">Prazo e política de revisão dependem do regulamento versionado. Decisões após homologação exigem análise específica.</p>`,button('Enviar solicitação','submit-appeal','primary-button'))}
function renderLeagueStandings(monthly, points, compact=false) {
 const people = [
  {id:'marcus',name:'Marcus',points:monthly?1820:680},
  {id:'kaique',name:'Kaique',points:monthly?1740:640},
  {id:'silas',name:'Silas',points:monthly?1630:602},
  {id:'carlos',name:'Carlos Eduardo',points,current:true}
 ].sort((a,b)=>b.points-a.points);
 // Equal scores share a position until the tie-breaking regulation is approved.
 const position = person => people.findIndex(p=>p.points===person.points)+1;
 const portrait = person => `<span class="member-photo member-${person.id}" role="img" aria-label="Foto de ${person.name}"></span>`;
 const podium = people.filter(p=>!p.current||state.rankingVisible).slice(0,3);
 return `<section class="league-standings" aria-label="Classificação demonstrativa">
  <p class="league-caption">Amostra de 4 participantes · Pontos de Impacto</p>
  <div class="league-podium">${podium.map((p,i)=>`<article class="league-podium-card podium-slot-${i+1}${p.current?' current':''}">
   <span class="league-place">${position(p)}º</span>${portrait(p)}<strong>${p.current?'Você':p.name}</strong><span class="league-score">${p.points.toLocaleString('pt-BR')} <small>pts</small></span>
  </article>`).join('')}</div>
  <div class="league-list">${people.filter(p=>!compact||p.current).map(p=>`<article class="league-row${p.current?' current':''}" ${p.current?'aria-label="Sua classificação"':''}>
   <span class="league-place">${position(p)}º</span>${portrait(p)}<div class="league-name"><strong>${p.current?'Você':p.name}</strong><small>${p.current?(state.rankingVisible?'Carlos Eduardo':'Só você pode ver seu perfil'):'Participante'}</small></div><strong class="league-score">${p.points.toLocaleString('pt-BR')}<small>pts</small></strong>
  </article>`).join('')}</div>
 </section>`;
}
renderRanking = function(){const monthly=state.cycle==='month';const points=(monthly?1240:340)+competitive(monthly?'month':'week');return screen('Liga e Temporada',`<div class="move-tabs">${button('Liga semanal','week',monthly?'secondary-button':'primary-button')}${button('Temporada mensal','month',monthly?'primary-button':'secondary-button')}</div><h1>${monthly?'Temporada mensal':'Liga semanal'}</h1><p>${monthly?demo.month:demo.week} · horário de São Paulo</p><span class="move-pill">Classificação provisória · simulada</span>
 ${renderLeagueStandings(monthly,points)}
 ${monthly?`<article class="move-prize">${icon('bolt',28)}<h2>Sua mobilidade pode pagar sua energia</h2><p>Incentivo em definição com parceiros</p><span class="move-pill move-warning">Incentivo em definição com parceiros</span><p>A publicação depende de orçamento reservado, regulamento, desempate, documentação, contestação e pagamento definidos.</p></article>`:row('Reconhecimento semanal','A Liga acompanha seu progresso de segunda a domingo. Não há benefício financeiro presumido.','trophy')}
 ${button('Entender pontuação e regras','ranking-rules')}`)};
renderRankingRules = function(){return screen('Regras dos ciclos',`<h1>Impacto e recompensa têm papéis diferentes</h1>${row('Pontos de Impacto','Somente jornadas elegíveis contribuem para rankings. Confiança é critério de elegibilidade, não multiplicador.','leaf')}${row('Rotas ilimitadas','Todas as jornadas validadas, livres ou de campanha, contam na Liga e na Temporada. Integração continua sendo uma única jornada.','route')}${row('Duas conquistas por semana','Cada uma das duas primeiras rotas livres validadas da semana libera seu próprio selo e cartão. Campanhas não ocupam essas conquistas. As demais rotas continuam somando impacto.','badge')}${row('Período da jornada','O término define o dia, a semana e o mês em São Paulo. A validação libera o resultado sem mudar o período.','clock')}${row('Pontos Soul','Benefícios financiados por campanhas não entram no ranking. Compras, cliques e compartilhamentos não geram Pontos de Impacto.','wallet')}${row('Apuração e desempate','Consultar este painel não homologa ciclos nem concede prêmios. Critérios de desempate e revisão dependem do regulamento versionado.','shield')}<label class="consent-option"><input type="checkbox" data-preference="ranking" ${state.rankingVisible?'checked':''}><span><strong>Aparecer na classificação pública</strong><span>Seu histórico e sua pontuação permanecem acessíveis para você.</span></span></label><p class="move-demo">68 pontos por jornada é um valor fixo de cenário. A fórmula 0–100 e os limites de distância/tempo não estão implementados nem definidos neste protótipo.</p>`)};
renderShare = function(){const j=selectedResult();if(!j||j.status!=='validated')return renderHistory();return screen('Compartilhar conquista',`<h1>Seu caminho merece ser lembrado</h1><p>Confira o cartão antes de compartilhar.</p><article class="share-card"><span class="share-brand">${icon('leaf')} SOULMOVE</span><h2>${j.recognition?(j.recognition.ordinal===1?'Primeiro passo':'Ritmo da semana'):'Mais uma jornada de ônibus!'}</h2>${j.recognition?`<p>Carlos Eduardo · ${j.recognition.position}º na amostra da Liga</p><p>${j.recognition.points} Pontos de Impacto no desbloqueio · selo ${j.recognition.ordinal}/2</p>`:''}<p>${j.mode==='free'?'Jornada livre':'Campanha VIVA · demonstrativa'}</p><div class="share-stats"><div><strong>${j.distance.toFixed(1)} km</strong><span>ônibus</span></div><div><strong>${j.impact}</strong><span>Pontos de Impacto*</span></div><div><strong>${j.avoided} kg</strong><span>CO₂ estimado*</span></div></div><p>${j.reward?'+12 Pontos Soul · meta da campanha concluída':'Uma jornada, um resultado, mesmo com integração.'}</p><small>*Valores simulados; sem crédito de carbono. Sem localização ou horário individual.</small></article><div class="action-stack">${button('Publicar no Clipz (simulação)','share-clipz')}${button('Compartilhar em outros apps','share-external')}${button('Salvar cartão','save-card')}${button('Voltar ao resultado','result')}</div>`)};
renderBenefit = function(){return screen('Seu benefício',`<h1>${state.rewardIssued?'Meta concluída, benefício disponível':'Benefício ainda bloqueado'}</h1><p>${state.campaignProgress}/3 jornadas elegíveis na campanha VIVA.</p>${row('Pontos Soul',state.rewardIssued?'12 pontos creditados uma única vez na carteira demonstrativa.':'Complete a meta da campanha para receber 12 pontos.','wallet')}${row('Oferta de 15%','Condição demonstrativa válida até 30/09/2026. Encerrar a campanha não cancela este benefício dentro da validade.','gift')}${state.rewardIssued?button('Abrir oferta','activate-offer','primary-button'):button('Ver condições da campanha','open-campaign')}${button('Ver carteira','wallet-detail')}`)};
renderOffer = function(){return screen('Oferta VIVA',`<h1>15% de desconto</h1><p>Abrir a oferta não registra uma compra. Você escolhe se deseja utilizar o benefício.</p>${state.couponIssued?`<div class="coupon"><span>Cupom demonstrativo emitido</span><code>MOVE15</code></div>${button('Copiar cupom','copy-coupon')}${button('Simular compra confirmada','register-conversion','primary-button')}`:button('Emitir cupom demonstrativo','issue-coupon','primary-button')}${button('Apenas consultar e voltar','benefit')}<p class="move-demo">O protótipo não efetua compras ou pagamentos reais.</p>`)};
function campaignMetrics(){const list=state.journeys.filter(j=>j.mode==='campaign');return {participants:312+(state.joined?1:0),started:274+list.filter(j=>j.status!=='cancelled').length+(state.currentJourney?.mode==='campaign'?1:0),validated:231+list.filter(j=>j.campaignEligible).length,benefits:188+(state.rewardIssued?1:0),opened:96+(state.offerOpened?1:0),coupons:52+(state.couponIssued?1:0),conversions:27+(state.conversion?1:0),distance:1940.4+list.filter(j=>j.campaignEligible).reduce((n,j)=>n+j.distance,0)}}
function money(n){return n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}
function reportText(){const m=campaignMetrics();return `SoulBusiness — VIVA\nRELATÓRIO DEMONSTRATIVO ${state.campaignStatus==='closed'?'FINAL HOMOLOGADO':'PROVISÓRIO'}\nVersão: ${state.reportVersion||1}\nCorte e geração simulados: 13/09/2026 12:00 America/Sao_Paulo\nCampanha: 10–25/09/2026 · Regras demo v1\nParticipantes: ${m.participants}\nJornadas iniciadas: ${m.started}\nJornadas elegíveis validadas: ${m.validated}\nTaxa de validação: ${(100*m.validated/m.started).toFixed(1)}%\nDistância elegível: ${m.distance.toFixed(1)} km\nEmissões evitadas: ${(m.distance*1.1/8.4).toFixed(2)} kg, estimativa ilustrativa sem metodologia auditada\nBenefícios: ${m.benefits}\nOfertas abertas: ${m.opened}\nCupons emitidos: ${m.coupons}\nCupons utilizados / compras confirmadas: ${m.conversions}\nOrçamento demo: R$ 12.000,00\nUtilizado: ${money(6768+(state.rewardIssued?36:0))}\nReservado: ${money((state.campaignStatus==='closed'?0:1800)+state.reservation)}\nSaldo disponível: ${money(5232-(state.rewardIssued?36:0)-(state.campaignStatus==='closed'?0:1800)-state.reservation)}\nCusto por jornada validada: ${money((6768+(state.rewardIssued?36:0))/m.validated)}\nCusto por conversão atribuída: ${money((6768+(state.rewardIssued?36:0))/m.conversions)}\nNão representa créditos de carbono. Dados agregados, simulados. O valor de R$ 36 é custo ilustrativo do pacote, não taxa de conversão dos Pontos Soul. Benefícios emitidos preservam validade; eventos tardios exigem nova versão. Destino do saldo depende de contrato.\n`}
function downloadText(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
renderBusiness = function(){const m=campaignMetrics(),used=6768+(state.rewardIssued?36:0);return `<div class="business-stage"><section class="business-app"><aside class="business-sidebar"><div class="business-brand">soul<span>business</span></div><nav class="business-nav">${button('Visão geral','business-home')}${button('Configurar campanha','configure-campaign')}${button('Encerramento e relatório','close-campaign-view')}</nav></aside><main class="business-main"><header class="business-heading"><div><h1>${state.businessView==='config'?'Configuração da campanha':state.businessView==='closing'?'Encerramento e relatório':'Sua jornada vale mais'}</h1><p>VIVA · dados e operação simulados</p></div><span class="demo-badge">${state.campaignStatus==='active'?'Ativa':state.campaignStatus==='closing'?'Em encerramento':'Encerrada'}</span></header>
 ${state.businessView==='config'?`<article class="dashboard-panel"><h2>Regras da edição demonstrativa</h2>${row('Período e público','10–25/09/2026 · usuários SoulUP em São Paulo')}${row('Meta e linhas','3 jornadas; D01 e D02; todos os trechos elegíveis; até 2 por dia')}${row('Limite por participante','1 recompensa: 12 Pontos Soul + oferta de 15%. Cobertura reservada na adesão.')}${row('Orçamento','R$ 12.000 fictícios; custo ilustrativo de R$ 36 por pacote. Não é cotação dos Pontos Soul.')}<label class="move-field">Título do rascunho<input id="draft-title" maxlength="80" value="${escapeHtml(state.draftTitle||campaign.title)}"></label>${button('Salvar rascunho para análise SoulUP','save-draft','primary-button')}${state.campaignDraft?row('Rascunho enviado','A campanha ativa não foi alterada. Publicação e alterações financeiras exigem nova verificação e autorização SoulUP.'):''}</article>`:state.businessView==='closing'?`<article class="dashboard-panel"><h2>Fechamento controlado</h2>${row('Encerramento antecipado','O patrocinador solicita; um operador SoulUP analisa contrato e impacto antes de autorizar.')}${row('Corte e jornadas em andamento','Após autorização, novas adesões e inícios são bloqueados. Jornadas anteriores seguem a janela das regras aceitas; seu prazo numérico ainda é uma dependência.')}${row('Conciliação','Reservas, recompensas, contestações e conversões devem ser resolvidas antes do relatório final.')}${row('Validade dos benefícios','Encerramento não cancela cupons emitidos. Eventos tardios seguem política de versão.')}<label class="move-field">Motivo do encerramento antecipado<textarea id="close-reason" rows="3" maxlength="300"></textarea></label>${state.campaignStatus==='active'?button('Solicitar encerramento','request-close','primary-button'):state.campaignStatus==='closing'?button('Simular homologação pelo operador SoulUP','homologate','primary-button'):row('Relatório final homologado',`Versão ${state.reportVersion}. Trilha demonstrativa preservada.`)}${state.closeRequested?`<p>Solicitação em análise. A campanha segue ativa até a autorização.</p>${button('Simular autorização do operador SoulUP','authorize-close')}`:''}${button('Exportar relatório '+(state.campaignStatus==='closed'?'final':'provisório'),'export-report')}</article>`:`
 <section class="metric-grid">${[['Participantes',m.participants],['Jornadas elegíveis',m.validated],['Benefícios emitidos',m.benefits],['Compras confirmadas',m.conversions]].map(([name,val])=>`<article class="metric-card"><span>${name}</span><strong>${val}</strong><small>Eventos únicos simulados</small></article>`).join('')}</section>
 <section class="dashboard-grid"><article class="dashboard-panel"><h2>Da adesão à conversão</h2>${[['Adesões',m.participants],['Jornadas iniciadas',m.started],['Validadas elegíveis',m.validated],['Ofertas abertas',m.opened],['Cupons emitidos',m.coupons],['Cupons utilizados',m.conversions],['Compras confirmadas',m.conversions]].map(([name,val])=>`<div class="ready-row"><span>${name}</span><strong>${val}</strong></div>`).join('')}<p>Taxa de validação: ${(m.validated/m.started*100).toFixed(1)}%. Abertura de oferta não equivale a compra.</p></article>
 <article class="dashboard-panel"><h2>Mobilidade e impacto</h2>${row('Distância elegível',m.distance.toFixed(1)+' km de ônibus','route')}${row('Emissões evitadas estimadas',(m.distance*1.1/8.4).toFixed(2)+' kg ilustrativos. Sem crédito de carbono.','leaf')}<label class="move-field">Recorte agregado<select id="business-zone"><option value="all" ${state.businessZone==='all'?'selected':''}>Todas as zonas</option><option value="small" ${state.businessZone==='small'?'selected':''}>Recorte com poucos participantes</option></select></label>${state.businessZone==='small'?row('Recorte protegido','Grupo pequeno: dados suprimidos para reduzir risco de identificação. Taxas deste recorte: não calculáveis.'):'<p>Distribuição demonstrativa: Leste 36% · Sul 28% · Norte 21% · Oeste/Centro 15%.</p>'}</article></section>
 <article class="dashboard-panel"><h2>Orçamento e cobertura</h2><div class="move-finance">${[['Total',12000],['Utilizado',used],['Reservado',(state.campaignStatus==='closed'?0:1800)+state.reservation],['Disponível',12000-used-(state.campaignStatus==='closed'?0:1800)-state.reservation]].map(([label,val])=>`<div><span>${label}</span><strong>${money(val)}</strong></div>`).join('')}</div><p>Custo por jornada validada: ${money(used/m.validated)} · custo por conversão atribuída: ${money(used/m.conversions)}.</p><p>A adesão reserva um pacote por participante. O crédito consome a reserva sem duplicação.</p>${button('Exportar relatório provisório','export-report')}</article>`}
 <div class="privacy-banner">Indicadores agregados e simulados. Sem nomes, trajetos individuais, documentos ou evidências. Custos e metodologia ambiental precisam de validação para produção.</div></main></section></div>`};
const legacyRenderUser=renderUser;
renderUser=function(){const routes={missions:renderMissions,'public-achievement':renderPublicAchievement,'move-home':renderMoveHome,history:renderHistory,integration:renderIntegration,appeal:renderAppeal,'cancel-confirm':()=>screen('Cancelar jornada',`<h1>Encerrar sem validar?</h1><p>A coleta será interrompida e a jornada ficará no histórico como cancelada, sem pontos ou recompensa.</p>${button('Continuar jornada','resume-journey')}`,button('Confirmar cancelamento','cancel-confirm','primary-button'))};return routes[state.screen]?routes[state.screen]():legacyRenderUser()};
// Rendering never starts/restarts collection or issues points.
render=function(){document.querySelectorAll('[data-perspective]').forEach(b=>b.classList.toggle('active',b.dataset.perspective===state.perspective));root.innerHTML=state.perspective==='business'?renderBusiness():renderUser()};
function beginMode(mode){if(state.currentJourney){navigate(state.currentJourney.processing?'validation':state.currentJourney.ended?'proof':'journey');return}state.permissionOnly=false;state.mode=mode;state.proofType='';navigate(state.consentLocation&&state.consentRules?'ready':'consent')}
function enterBusiness(view){clearJourneyTimers();state.perspective='business';state.businessView=view;render()}
// Capture only remodeled actions; legacy social/catalog interactions remain intact.
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
 const handlers={
  'move-home':()=>navigate('move-home'),'free-journey':()=>beginMode('free'),history:()=>navigate('history'),permissions:()=>{state.permissionOnly=true;navigate('consent')},
  missions:()=>{state.missionsFilter='all';navigate('missions')},'filter-missions':()=>{state.missionsFilter=el.dataset.filter;render()},'completed-missions':()=>{state.missionsFilter='completed';navigate('missions')},'public-achievement':()=>navigate('public-achievement'),
  'open-campaign':()=>{if(state.screen!=='campaign')state.campaignReturn=state.screen;navigate('campaign')},join:()=>{if(!state.campaignAccepted||state.campaignStatus!=='active')return;if(!state.joined){state.joined=true;state.reservation=demo.rewardBudget}beginMode('campaign')},
  'consent-continue':()=>{if(!state.consentLocation||!state.consentRules)return;if(state.permissionOnly){state.permissionOnly=false;navigate('move-home')}else navigate('ready')},
  revoke:()=>{state.consentLocation=false;if(state.currentJourney){finalizeJourney('cancelled');clearJourneyTimers()}navigate('consent');showToast('Autorização revogada. Nenhuma coleta em andamento.')},
  'start-journey':()=>{if(state.currentJourney||!state.consentLocation||!state.consentRules)return;if(state.mode==='campaign'&&(!state.joined||state.campaignStatus!=='active')){showToast('Campanha indisponível para novos inícios');return}state.outcome=document.querySelector('#demo-outcome').value;state.currentJourney={id:crypto.randomUUID(),mode:state.mode,segments:[{line:document.querySelector('#bus-line').value,direction:document.querySelector('#bus-direction').value}],ended:false};state.journeyStarted=true;navigate('journey')},
  integration:()=>navigate('integration'),'add-segment':()=>{if(!state.currentJourney||state.currentJourney.ended)return;state.currentJourney.segments.push({line:document.querySelector('#bus-line').value,direction:document.querySelector('#bus-direction').value});navigate('journey')},
  'finish-journey':()=>{if(!state.currentJourney)return;state.currentJourney.endedAt ||= demoEnd();state.currentJourney.ended=true;navigate('proof')},'submit-proof':()=>beginValidation(),'cancel-request':()=>navigate('cancel-confirm'),'resume-journey':()=>navigate('journey'),'cancel-confirm':()=>{finalizeJourney('cancelled');navigate('result')},
  result:()=>navigate('result'),'history-result':()=>{state.selectedJourney=el.dataset.id;navigate('result')},appeal:()=>navigate('appeal'),
  'submit-appeal':()=>{const j=selectedResult(),reason=document.querySelector('#appeal-reason')?.value.trim();if(!reason){showToast('Informe a justificativa');return}if(!j||j.appeal||!['inconclusive','rejected'].includes(j.status))return;j.appeal='SM-'+String(state.journeys.indexOf(j)+1).padStart(4,'0');j.appealReason=reason;navigate('result');showToast('Solicitação registrada para análise')},
  week:()=>{state.cycle='week';navigate('ranking')},month:()=>{state.cycle='month';navigate('ranking')},ranking:()=>navigate('ranking'),
  'recognition-share':()=>{const j=state.journeys.find(x=>x.id===el.dataset.id&&x.recognition);if(j){state.selectedJourney=j.id;navigate('share')}},share:()=>navigate('share'),'share-clipz':()=>{state.sharePublished=true;state.shareChannel='Clipz';showToast('Publicação demonstrativa no Clipz registrada')},
  'share-external':async()=>{const j=selectedResult();if(!j)return;const data={title:'Minha conquista SoulMove',text:`Jornada de ônibus: ${j.distance.toFixed(1)} km. ${j.impact} Pontos de Impacto ilustrativos. Demonstração SoulMove.`};if(!navigator.share){showToast('Compartilhamento indisponível. Use Salvar cartão.');return}try{await navigator.share(data);showToast('Solicitação aceita pelo dispositivo')}catch(e){showToast(e.name==='AbortError'?'Compartilhamento cancelado':'Não foi possível compartilhar')}},
  'save-card':()=>{const j=selectedResult();if(!j)return;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080"><rect width="1080" height="1080" rx="48" fill="#142848"/><g font-family="Arial" fill="white"><text x="80" y="130" font-size="40">SOULMOVE</text><text x="80" y="300" font-size="58">${j.recognition?(j.recognition.ordinal===1?'Primeiro passo':'Ritmo da semana'):'Minha jornada de ônibus'}</text>${j.recognition?`<text x="80" y="205" font-size="32">Carlos Eduardo · selo ${j.recognition.ordinal}/2 · ${j.recognition.position}º na amostra</text><text x="80" y="790" font-size="28">${j.recognition.points} Pontos de Impacto na Liga no desbloqueio</text>`:''}<text x="80" y="450" font-size="74">${j.distance.toFixed(1)} km · ${j.segments.length} trecho(s)</text><text x="80" y="580" font-size="48">${j.impact} Pontos de Impacto*</text><text x="80" y="700" font-size="40">${j.avoided} kg de emissões evitadas estimadas*</text><text x="80" y="880" font-size="26">*Demonstração. Valores ilustrativos, sem crédito de carbono.</text></g></svg>`;downloadText('soulmove-conquista.svg',svg,'image/svg+xml')},
  benefit:()=>navigate('benefit'),'activate-offer':()=>{if(!state.rewardIssued)return;state.offerOpened=true;navigate('offer')},'issue-coupon':()=>{if(!state.rewardIssued||!state.offerOpened)return;state.couponIssued=true;render()},'register-conversion':()=>{if(!state.couponIssued)return;state.conversion=true;navigate('conversion')},
  'copy-coupon':async()=>{try{await navigator.clipboard.writeText(campaign.coupon);showToast('Cupom copiado')}catch{showToast('Não foi possível copiar. Código: MOVE15')}},
  'business-home':()=>enterBusiness('overview'),'configure-campaign':()=>enterBusiness('config'),'close-campaign-view':()=>enterBusiness('closing'),
  'save-draft':()=>{const title=document.querySelector('#draft-title').value.trim();if(!title){showToast('Informe o título');return}state.draftTitle=title;state.campaignDraft=true;render()},
  'request-close':()=>{const reason=document.querySelector('#close-reason').value.trim();if(!reason){showToast('Informe o motivo');return}state.closeReason=reason;state.closeRequested=true;render()},
  'authorize-close':()=>{if(!state.closeRequested)return;state.closeRequested=false;state.campaignStatus='closing';state.reportVersion=1;render()},
  homologate:()=>{if(state.currentJourney?.mode==='campaign'||state.journeys.some(j=>j.mode==='campaign'&&j.appeal)){showToast('Há jornadas ou contestações pendentes. Relatório permanece provisório.');return}if(state.campaignStatus!=='closing')return;state.campaignStatus='closed';state.reservation=0;state.reportVersion+=1;render()},
  'export-report':()=>downloadText('soulbusiness-viva-relatorio.txt',reportText()),
  back:()=>{if(state.screen==='wallet'){navigate(state.walletReturn||'feed');return}if(state.screen==='marketplace'){navigate(state.marketplaceReturn||'feed');return}if(state.screen==='wallet-detail'){navigate('wallet');return}if(state.screen==='missions'&&state.missionsFilter==='completed'){state.missionsFilter='all';render();return}const parent={campaign:state.campaignReturn,'move-home':'missions',missions:'feed','public-achievement':'feed',ready:state.mode==='campaign'?'campaign':'move-home',consent:state.permissionOnly?'move-home':state.mode==='campaign'?'campaign':'move-home',history:'move-home',ranking:'move-home','ranking-rules':'ranking',result:'history',share:'result',appeal:'result',integration:'journey',proof:'proof',journey:'journey',benefit:'move-home',offer:'benefit',comments:state.commentsReturn};if(state.screen==='proof'){showToast('A coleta já foi encerrada. Envie para validação.');return}navigate(parent[state.screen]||'feed')}
 };
 if(handlers[action]){event.preventDefault();event.stopImmediatePropagation();await handlers[action]()}
},true);
document.addEventListener('change',event=>{if(event.target.id==='campaign-accept'){state.campaignAccepted=event.target.checked;render()}if(event.target.id==='business-zone'){state.businessZone=event.target.value;render()}},true);
function setPresentationMode(active) {
 document.body.classList.toggle('presentation-mode',active);
 document.querySelector('.prototype-toolbar').hidden=active;
 document.querySelector('#presentation-exit').hidden=!active;
 (active?document.querySelector('#presentation-exit'):document.querySelector('#presentation-start')).focus();
}
document.querySelector('#presentation-start').addEventListener('click',()=>setPresentationMode(true));
document.querySelector('#presentation-exit').addEventListener('click',()=>setPresentationMode(false));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('presentation-mode'))setPresentationMode(false)});
render();
